  ["MEW"] = { text = "Como puede aprender<NEXT>cualquier movimiento,<NEXT>algunos empezaron", text2 = "a investigar si es<NEXT>el ancestro de<NEXT>todos los POKéMON." },
  ["MEWTWO"] = { text = "Se dice que descansa<NEXT>en una cueva<NEXT>inexplorada. Este", text2 = "POKéMON fue creado<NEXT>solo para el<NEXT>combate." },
  ["MILTANK"] = { text = "Para ordeñar a un<NEXT>MILTANK, hay que<NEXT>tener maña para", text2 = "tirar rítmicamente<NEXT>de sus ubres hacia<NEXT>arriba y abajo." },
  ["MISDREAVUS"] = { text = "Le encanta ver a la<NEXT>gente asustada.<NEXT>Los asusta", text2 = "gritando fuerte o<NEXT>apareciendo de<NEXT>repente." },
  ["MOLTRES"] = { text = "POKéMON pájaro<NEXT>legendario. Se dice<NEXT>que migra desde el", text2 = "sur junto con la<NEXT>llegada de la<NEXT>primavera." },
  ["MR__MIME"] = { text = "Usa el misterioso<NEXT>poder que tiene en<NEXT>sus dedos para", text2 = "solidificar el aire<NEXT>en una pared<NEXT>invisible." },
  ["MUK"] = { text = "Al moverse, un<NEXT>veneno muy fuerte<NEXT>se filtra de él,", text2 = "dejando el suelo<NEXT>estéril durante<NEXT>tres años." },
  ["MURKROW"] = { text = "Esconde cualquier<NEXT>objeto brillante<NEXT>en un lugar", text2 = "secreto. MURKROW y<NEXT>MEOWTH roban los<NEXT>tesoros del otro." },
  ["NATU"] = { text = "Es extremadamente<NEXT>bueno trepando<NEXT>troncos y le gusta", text2 = "comer los brotes<NEXT>nuevos de los<NEXT>árboles." },
  ["NIDOKING"] = { text = "Usa sus brazos,<NEXT>piernas y cola<NEXT>para atacar con", text2 = "fuerza. El combate<NEXT>cuerpo a cuerpo es<NEXT>su especialidad." },
  ["NIDOQUEEN"] = { text = "Las duras escamas<NEXT>que cubren su<NEXT>cuerpo sirven de", text2 = "excelente protec-<NEXT>ción contra<NEXT>cualquier ataque." },
  ["NIDORAN_F"] = { text = "Pequeña y muy<NEXT>dócil, se protege<NEXT>con su pequeño", text2 = "cuerno venenoso<NEXT>cuando es<NEXT>atacada." },
  ["NIDORAN_M"] = { text = "Mueve sus grandes<NEXT>orejas en muchas<NEXT>direcciones para", text2 = "detectar el peligro<NEXT>de inmediato." },
  ["NIDORINA"] = { text = "Tiene una naturaleza<NEXT>dócil. Si se ve<NEXT>amenazada, levanta", text2 = "las púas que tiene<NEXT>por todo su<NEXT>cuerpo." },
  ["NIDORINO"] = { text = "Se agita fácilmente<NEXT>y usa su cuerno<NEXT>para atacar en", text2 = "cuanto nota a un<NEXT>atacante." },
  ["NINETALES"] = { text = "Se dice que vive<NEXT>mil años, y cada<NEXT>una de sus colas", text2 = "está cargada de<NEXT>poderes sobre-<NEXT>naturales." },
  ["NOCTOWL"] = { text = "Sus plumas tan<NEXT>suaves no hacen<NEXT>ruido al volar.", text2 = "Se acerca en<NEXT>silencio a su presa<NEXT>sin ser detectado." },
  ["OCTILLERY"] = { text = "Su instinto es<NEXT>enterrarse en<NEXT>agujeros. A menudo", text2 = "roba los nidos de<NEXT>otros para dormir<NEXT>en ellos." },
  ["ODDISH"] = { text = "Durante el día,<NEXT>se queda bajo<NEXT>tierra para evitar", text2 = "el sol. Crece<NEXT>bañándose en la<NEXT>luz de la luna." },
  ["OMANYTE"] = { text = "En tiempos prehis-<NEXT>tóricos, nadaba en<NEXT>el fondo del mar,", text2 = "comiendo plancton.<NEXT>Sus fósiles se<NEXT>encuentran a veces." },
  ["OMASTAR"] = { text = "Su pesada concha<NEXT>le permitía llegar<NEXT>solo a comida", text2 = "cercana. Esta podría<NEXT>ser la razón de<NEXT>su extinción." },
  ["ONIX"] = { text = "Al excavar en el<NEXT>suelo, absorbe<NEXT>muchos objetos", text2 = "duros. Esto es lo<NEXT>que hace su cuerpo<NEXT>tan sólido." },
  ["PARAS"] = { text = "El tochukaso que<NEXT>crece en la espalda<NEXT>de este POKéMON", text2 = "le ordena extraer<NEXT>jugo de los<NEXT>troncos." },
  ["PARASECT"] = { text = "Cuando no queda<NEXT>nada que extraer<NEXT>del bicho, las", text2 = "setas de su espalda<NEXT>dejan esporas en<NEXT>los huevos." },
  ["PERSIAN"] = { text = "Tras su aspecto<NEXT>ágil y elegante<NEXT>se esconde un lado", text2 = "bárbaro. Despedaza<NEXT>a su presa por un<NEXT>mero capricho." },
  ["PHANPY"] = { text = "Durante las horas<NEXT>de la mañana, llega<NEXT>a la orilla donde", text2 = "usa su trompa para<NEXT>darse una ducha<NEXT>con destreza." },
  ["PICHU"] = { text = "No sabe almacenar<NEXT>energía eléctrica.<NEXT>Cualquier tipo de", text2 = "choque hace que<NEXT>descargue energía<NEXT>espontáneamente." },
  ["PIDGEOT"] = { text = "Su visión destaca<NEXT>y le permite ver<NEXT>MAGIKARP, incluso", text2 = "volando a más de<NEXT>1000 metros de<NEXT>altura." },
  ["PIDGEOTTO"] = { text = "Vuela lentamente<NEXT>en un patrón<NEXT>circular, mientras", text2 = "busca con atención<NEXT>a su presa." },
  ["PIDGEY"] = { text = "Bate sus alas<NEXT>rápidamente en la<NEXT>hierba, creando", text2 = "una nube de polvo<NEXT>que saca a los<NEXT>insectos." },
  ["PIKACHU"] = { text = "Cuando se enfada,<NEXT>descarga inmediata-<NEXT>mente la energía", text2 = "almacenada en las<NEXT>bolsas de sus<NEXT>mejillas." },
  ["PILOSWINE"] = { text = "Aunque sus patas<NEXT>son cortas, sus<NEXT>pezuñas rugosas", text2 = "evitan que resbale,<NEXT>incluso en suelo<NEXT>helado." },
  ["PINECO"] = { text = "Escupe un fluido<NEXT>que usa para pegar<NEXT>corteza de árbol", text2 = "a su cuerpo. El<NEXT>fluido se endurece<NEXT>al tocar el aire." },
  ["PINSIR"] = { text = "Cuando la tempera-<NEXT>tura baja por la<NEXT>noche, duerme en", text2 = "las copas de los<NEXT>árboles o raíces<NEXT>donde está oculto." },
  ["POLITOED"] = { text = "Cuando expande su<NEXT>garganta para<NEXT>croar una melodía,", text2 = "los POLIWAG y<NEXT>POLIWHIRL cercanos<NEXT>se reúnen." },
  ["POLIWAG"] = { text = "El remolino de su<NEXT>barriga es su<NEXT>interior que se ve", text2 = "a través de la piel.<NEXT>Se ve más claro<NEXT>tras comer." },
  ["POLIWHIRL"] = { text = "Aunque es hábil<NEXT>caminando, prefiere<NEXT>vivir bajo el agua", text2 = "donde hay menos<NEXT>peligro." },
  ["POLIWRATH"] = { text = "Puede usar sus<NEXT>brazos y piernas<NEXT>bien desarrollados", text2 = "para correr sobre<NEXT>el agua por un<NEXT>instante." },
  ["PONYTA"] = { text = "Entrenar saltando<NEXT>sobre hierba que<NEXT>crece cada día", text2 = "le ha hecho un<NEXT>saltador de clase<NEXT>mundial." },
  ["PORYGON"] = { text = "Un POKéMON<NEXT>artificial creado<NEXT>tras una larga", text2 = "investigación, solo<NEXT>hace lo que está<NEXT>en su programa." },
  ["PORYGON2"] = { text = "Este POKéMON creado<NEXT>por el hombre evolu-<NEXT>cionó con la última", text2 = "tecnología. Puede<NEXT>tener reacciones no<NEXT>programadas." },
  ["PRIMEAPE"] = { text = "Se enfada con<NEXT>cualquiera por nada<NEXT>y los persigue", text2 = "hasta el fin del<NEXT>mundo sin descanso." },
  ["PSYDUCK"] = { text = "Solo usa su poder<NEXT>psíquico cuando su<NEXT>cerebro dormido", text2 = "recupera la acti-<NEXT>vidad por casuali-<NEXT>dad." },
  ["PUPITAR"] = { text = "No para quieto ni<NEXT>siendo una pupa.<NEXT>Ya tiene brazos y", text2 = "piernas bajo su<NEXT>caparazón sólido." },
  ["QUAGSIRE"] = { text = "Su cuerpo es muy<NEXT>viscoso. Al nadar,<NEXT>golpea su cabeza", text2 = "contra el fondo y<NEXT>parece no impor-<NEXT>tarle lo más mínimo." },
  ["QUILAVA"] = { text = "Antes de luchar, da<NEXT>la espalda al rival<NEXT>para mostrarle", text2 = "con qué ferocidad<NEXT>arde su fuego." },
  ["QWILFISH"] = { text = "Ante un rival más<NEXT>grande, traga tanta<NEXT>agua como puede", text2 = "para alcanzar el<NEXT>tamaño del adver-<NEXT>sario." },
  ["RAICHU"] = { text = "Si sus bolsas de<NEXT>electricidad se<NEXT>vacían, levanta la", text2 = "cola para capturar<NEXT>electricidad de<NEXT>la atmósfera." },
  ["RAIKOU"] = { text = "Este violento<NEXT>POKéMON almacena<NEXT>energía dentro,", text2 = "y recorre las tie-<NEXT>rras disparando<NEXT>descargas." },
  ["RAPIDASH"] = { text = "Le encanta galopar.<NEXT>Cuanto más rápido<NEXT>va, más largas", text2 = "se vuelven las<NEXT>llamas oscilantes<NEXT>de su crin." },
  ["RATICATE"] = { text = "Las membranas de<NEXT>sus patas traseras<NEXT>le permiten cruzar", text2 = "ríos. Busca comida<NEXT>en amplias zonas." },
  ["RATTATA"] = { text = "Su gran vitalidad<NEXT>le permite vivir en<NEXT>cualquier parte.", text2 = "Además, se multi-<NEXT>plica muy de<NEXT>prisa." },
  ["REMORAID"] = { text = "Para escapar de un<NEXT>atacante, puede<NEXT>disparar agua y", text2 = "usar la fuerza de<NEXT>retroceso para<NEXT>nadar hacia atrás." },
  ["RHYDON"] = { text = "Girando su cuerno<NEXT>con forma de tala-<NEXT>dro, puede romper", text2 = "fácilmente hasta el<NEXT>diamante más bruto." },
  ["RHYHORN"] = { text = "Solo puede recor-<NEXT>dar una cosa a la<NEXT>vez. Al empezar", text2 = "a correr, olvida<NEXT>por qué lo hacía." },
  ["SANDSHREW"] = { text = "Prefiere los luga-<NEXT>res secos y arenosos<NEXT>porque usa la arena", text2 = "para protegerse<NEXT>cuando se siente<NEXT>amenazado." },
  ["SANDSLASH"] = { text = "Sube bien a los<NEXT>árboles, se enrosca<NEXT>en bola con púas", text2 = "y ataca a sus ene-<NEXT>migos desde arriba." },
  ["SCIZOR"] = { text = "Las pinzas de este<NEXT>POKéMON contienen<NEXT>acero y pueden", text2 = "reducir a trozos<NEXT>cualquier objeto<NEXT>duro que agarren." },
  ["SCYTHER"] = { text = "Está muy orgulloso<NEXT>de su velocidad.<NEXT>Se mueve tan rápido", text2 = "que el rival ni ve<NEXT>qué lo derribó." },
  ["SEADRA"] = { text = "El macho cría a<NEXT>los jóvenes. Si se<NEXT>le acerca alguien,", text2 = "usa sus púas tóxi-<NEXT>cas para ahuyentar<NEXT>al intruso." },
  ["SEAKING"] = { text = "En otoño, los ma-<NEXT>chos patrullan la<NEXT>zona de sus nidos", text2 = "para proteger a su<NEXT>descendencia." },
  ["SEEL"] = { text = "Su pelaje azul<NEXT>claro lo protege<NEXT>del frío. Ama los", text2 = "océanos repletos<NEXT>de grandes tempi-<NEXT>danos." },
  ["SENTRET"] = { text = "Cuando hace de<NEXT>centinela, avisa a<NEXT>los demás gri-<NEXT>tando y dando", text2 = "golpes en el suelo<NEXT>con su cola." },
  ["SHELLDER"] = { text = "Agarrarse a un<NEXT>rival deja sus<NEXT>partes vulnerables<NEXT>expuestas, por", text2 = "lo que solo usa<NEXT>este ataque como<NEXT>último recurso." },
  ["SHUCKLE"] = { text = "El fluido de sus<NEXT>patas abre nidos<NEXT>en las rocas y se<NEXT>mezcla con BAYAS", text2 = "para hacer una<NEXT>bebida." },
  ["SKARMORY"] = { text = "Las plumas que<NEXT>muda son muy afila-<NEXT>das. Se dice que", text2 = "antiguamente la<NEXT>gente las usaba<NEXT>como espadas." },
  ["SKIPLOOM"] = { text = "En cuanto llueve,<NEXT>cierra su flor y<NEXT>se oculta bajo la<NEXT>sombra de un árbol", text2 = "para no mojarse." },
  ["SLOWBRO"] = { text = "Un SHELLDER unido<NEXT>no se suelta por<NEXT>el sabroso jugo<NEXT>que segrega su cola.", text2 = "" },
  ["SLOWKING"] = { text = "Cada vez que bos-<NEXT>teza, SHELLDER le<NEXT>inyecta más veneno,<NEXT>lo que lo hace", text2 = "más inteligente." },
  ["SLOWPOKE"] = { text = "Siempre está tan<NEXT>distraído que ni<NEXT>reacciona si le<NEXT>muerden su sabrosa", text2 = "cola." },
  ["SLUGMA"] = { text = "Se agrupan en zo-<NEXT>nas más calientes<NEXT>de lo normal. Si<NEXT>se enfría, su piel", text2 = "se endurece." },
  ["SMEARGLE"] = { text = "El color del flui-<NEXT>do misterioso de<NEXT>su cola está pre-<NEXT>determinado para", text2 = "cada SMEARGLE." },
  ["SMOOCHUM"] = { text = "La sensibilidad de<NEXT>sus labios se de-<NEXT>sarrolla muy rápi-<NEXT>do. Los usa para", text2 = "identificar obje-<NEXT>tos desconocidos." },
  ["SNEASEL"] = { text = "Este astuto POKé-<NEXT>MON se esconde<NEXT>al amparo de la<NEXT>oscuridad, espe-<NEXT>rando", text2 = "atacar a su presa." },
  ["SNORLAX"] = { text = "El estómago de este<NEXT>POKéMON es tan<NEXT>fuerte que comer<NEXT>comida en moho o", text2 = "podrida no le hace<NEXT>efecto." },
  ["SNUBBULL"] = { text = "En verdad es un<NEXT>POKéMON cobarde.<NEXT>Gruñe con anhelo<NEXT>para ocultar su", text2 = "miedo al rival." },
  ["SPEAROW"] = { text = "Para proteger su<NEXT>territorio, vuela<NEXT>sin cesar emi-<NEXT>tiendo gritos", text2 = "muy agudos." },
  ["SPINARAK"] = { text = "Si una presa cae<NEXT>en su nido de hilo<NEXT>tejido, espera sin<NEXT>moverse hasta que", text2 = "se hace de noche." },
  ["SQUIRTLE"] = { text = "Cuando se siente<NEXT>amenazado, mete<NEXT>las patas en su<NEXT>caparazón y dispa-<NEXT>ra", text2 = "agua por la boca." },
  ["STANTLER"] = { text = "Las bolas redondas<NEXT>de sus astas caí-<NEXT>das se pueden mo-<NEXT>ler en un polvo", text2 = "que ayuda a dor-<NEXT>mir." },
  ["STARMIE"] = { text = "Dicen que usa el<NEXT>núcleo de siete<NEXT>colores de su cuer-<NEXT>po para enviar", text2 = "ondas eléctricas<NEXT>al espacio exte-<NEXT>rior." },
  ["STARYU"] = { text = "Cuando las estre-<NEXT>llas brillan de<NEXT>noche, flota des-<NEXT>de el fondo mari-<NEXT>no", text2 = "y parpadea su<NEXT>núcleo central." },
  ["STEELIX"] = { text = "Las numerosas y<NEXT>pequeñas partícu-<NEXT>las de metal que<NEXT>cubren este POKé-<NEXT>MON", text2 = "reflejan muy bien<NEXT>la luz brillante." },
  ["SUDOWOODO"] = { text = "Si una rama se<NEXT>agita sin haber<NEXT>viento, es un<NEXT>SUDOWOODO, no un<NEXT>árbol.", text2 = "Se oculta de la<NEXT>lluvia." },
  ["SUICUNE"] = { text = "Este divino POKé-<NEXT>MON viaja por el<NEXT>mundo buscando<NEXT>siempre un manantial", text2 = "puro." },
  ["SUNFLORA"] = { text = "Al acercarse la<NEXT>época calurosa,<NEXT>los pétalos de la<NEXT>cara de este POKé-<NEXT>MON", text2 = "se vuelven más<NEXT>vivos y alegres." },
  ["SUNKERN"] = { text = "Es muy débil. Su<NEXT>único medio de<NEXT>defensa es agitar<NEXT>sus hojas con deses-<NEXT>peración", text2 = "ante su atacante." },
  ["SWINUB"] = { text = "Usa la punta de<NEXT>la nariz para bus-<NEXT>car comida. Es tan<NEXT>dura que ni el sue-<NEXT>lo helado", text2 = "es un problema." },
  ["TANGELA"] = { text = "Durante el comba-<NEXT>te, mueve sin cesar<NEXT>las lianas que<NEXT>cubren su cuerpo", text2 = "para irritar al<NEXT>rival." },
  ["TAUROS"] = { text = "Estos violentos<NEXT>POKéMON luchan<NEXT>contra otros miem-<NEXT>bros de su manada", text2 = "para demostrar su<NEXT>fuerza." },
  ["TEDDIURSA"] = { text = "Siempre lamiendo<NEXT>miel. Su palma<NEXT>sabe dulce por toda<NEXT>la miel que ha", text2 = "absorbido." },
  ["TENTACOOL"] = { text = "Mientras flota en<NEXT>las olas, usa sus<NEXT>tentáculos tóxi-<NEXT>cos para clavar", text2 = "todo lo que toca." },
  ["TENTACRUEL"] = { text = "Cuando sus 80 ten-<NEXT>táculos absorben<NEXT>agua, se estiran<NEXT>como una red para", text2 = "atrapar a su presa." },
  ["TOGEPI"] = { text = "Se considera un<NEXT>símbolo de buena<NEXT>suerte. Dicen que<NEXT>su caparazón está", text2 = "lleno de felici-<NEXT>dad." },
  ["TOGETIC"] = { text = "Aunque no bate<NEXT>mucho las alas, se<NEXT>mantiene en el<NEXT>aire mientras si-<NEXT>gue", text2 = "a su entrenador." },
  ["TOTODILE"] = { text = "Este bicho agre-<NEXT>sivo muerde cual-<NEXT>quier objeto en<NEXT>movimiento. No es", text2 = "nada aconsejable<NEXT>darle la espalda." },
  ["TYPHLOSION"] = { text = "Cuando el calor de<NEXT>su cuerpo hace que<NEXT>el aire tiemble,<NEXT>es señal de que", text2 = "está listo para<NEXT>luchar." },
  ["TYRANITAR"] = { text = "Con una sola de<NEXT>sus poderosas ma-<NEXT>nos, tiene el poder<NEXT>de hacer temblar", text2 = "el suelo y des-<NEXT>truir montañas." },
  ["TYROGUE"] = { text = "Para pulir sus<NEXT>habilidades de lu-<NEXT>cha, desafiará a<NEXT>cualquiera. Tiene", text2 = "un espíritu com-<NEXT>petitivo muy alto." },
  ["UMBREON"] = { text = "En las noches de<NEXT>luna llena, o al<NEXT>emocionarse, los<NEXT>aros de su cuerpo", text2 = "brillan de color<NEXT>amarillo." },
  ["UNOWN"] = { text = "Como existen dis-<NEXT>tintos tipos de<NEXT>UNOWN, se dice<NEXT>que deben de te-<NEXT>ner", text2 = "una gran variedad<NEXT>de habilidades." },
  ["URSARING"] = { text = "Aunque tiene un<NEXT>cuerpo grande, se<NEXT>le da muy bien su-<NEXT>bir a los árboles.<NEXT>Come", text2 = "y duerme en las<NEXT>copas." },
  ["VAPOREON"] = { text = "Usa las aletas de<NEXT>la punta de su<NEXT>cola para nadar,<NEXT>confundiéndose con", text2 = "el agua a la per-<NEXT>fección." },
  ["VENOMOTH"] = { text = "Las escamas que<NEXT>esparce paraliza-<NEXT>rán a cualquiera<NEXT>que las toque,", text2 = "impidiéndole estar<NEXT>de pie." },
  ["VENONAT"] = { text = "Los pequeños bi-<NEXT>chos que come solo<NEXT>salen de noche, así<NEXT>que duerme en un", text2 = "hueco de un árbol<NEXT>hasta el anochecer." },
  ["VENUSAUR"] = { text = "Al calentarse y<NEXT>absorber la luz<NEXT>solar, los pétalos<NEXT>de su flor despren-<NEXT>den", text2 = "una agradable fra-<NEXT>gancia." },
  ["VICTREEBEL"] = { text = "Una vez ingerido en<NEXT>el cuerpo de este<NEXT>POKéMON, hasta el<NEXT>objeto más duro", text2 = "se funde en nada." },
  ["VILEPLUME"] = { text = "Agitando sus gran-<NEXT>des pétalos, espar-<NEXT>ce polen tóxico<NEXT>por el aire, tiñién-<NEXT>dolo", text2 = "de amarillo." },
  ["VOLTORB"] = { text = "Durante el estudio<NEXT>de este POKéMON,<NEXT>se descubrió que<NEXT>sus componentes no", text2 = "se hallan en la<NEXT>naturaleza." },
  ["VULPIX"] = { text = "A medida que cre-<NEXT>ce, sus seis cáli-<NEXT>das colas se vuel-<NEXT>ven más hermosas,", text2 = "con un pelaje más<NEXT>lujoso." },
  ["WARTORTLE"] = { text = "Su larga y peluda<NEXT>cola es símbolo de<NEXT>longevidad, lo que<NEXT>lo hace muy popu-<NEXT>lar", text2 = "entre los ancianos." },
  ["WEEDLE"] = { text = "El aguijón de lo<NEXT>alto de su cabeza<NEXT>segrega un veneno<NEXT>fuerte. Usa este", text2 = "aguijón tóxico<NEXT>para defenderse." },
  ["WEEPINBELL"] = { text = "Cuando tiene ham-<NEXT>bre, agita sus ho-<NEXT>jas afiladas como<NEXT>cuchillas, cortan-<NEXT>do", text2 = "cualquier cosa<NEXT>cercana para co-<NEXT>mer." },
  ["WEEZING"] = { text = "Al inhalar gases<NEXT>venenosos de la<NEXT>basura, su cuerpo<NEXT>se expande y sus", text2 = "entrañas huelen<NEXT>mucho peor." },
  ["WIGGLYTUFF"] = { text = "El pelaje suave y<NEXT>esponjoso que cu-<NEXT>bre su cuerpo da<NEXT>tanta gusto que<NEXT>quien lo toca no", text2 = "puede parar." },
  ["WOBBUFFET"] = { text = "Para ocultar su<NEXT>negra cola, vive<NEXT>en una cueva os-", text2 = "cura y solo se<NEXT>mueve de noche." },
  ["WOOPER"] = { text = "Una membrana muco-<NEXT>sa cubre su cuer-<NEXT>po. Tocarlo con las<NEXT>manos desnudas", text2 = "causará un dolor<NEXT>punzante." },
  ["XATU"] = { text = "Una vez que empi-<NEXT>eza a meditar al<NEXT>amanecer, pasará<NEXT>todo el día antes", text2 = "de volver a mo-<NEXT>verse." },
  ["YANMA"] = { text = "Puede ver en to-<NEXT>das direcciones sin<NEXT>mover sus gran-<NEXT>des ojos, lo que<NEXT>le ayuda", text2 = "a detectar enemi-<NEXT>gos y comida al<NEXT>instante." },
  ["ZAPDOS"] = { text = "POKéMON pájaro<NEXT>legendario. Dicen<NEXT>que los rayos cau-<NEXT>sados al batir sus", text2 = "alas provocan tor-<NEXT>mentas en verano." },
  ["ZUBAT"] = { text = "Durante el día, se<NEXT>reúne con otros y<NEXT>cuelga de los te-<NEXT>chos de antiguos", text2 = "edificios y cue-<NEXT>vas." },
  ["entries"] = { text = "Se hipnotiza a sí<NEXT>mismo para poder<NEXT>teletransportarse<NEXT>si detecta peli-<NEXT>gro,", text2 = "incluso aunque<NEXT>esté dormido." },
}
